function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');toastTimer=2.8;}
function finish(which){ui.choice.classList.add('hidden');mode='ending';if(which==='kind'){moral=Math.min(100,moral+32);ui.endingEyebrow.textContent='A gentle light';ui.endingTitle.innerHTML='The vale <span>blooms</span>';ui.endingText.textContent='You shared the fire. Warm windows kindle across the Gloaming Vale, and the keeper’s lantern shines brighter than ever. Somewhere at your heel, your loyal hound gives a happy bark. The people will speak your name with gratitude.';}else{moral=Math.max(0,moral-45);player.will=100;ui.endingEyebrow.textContent='A hungry light';ui.endingTitle.innerHTML='The vale <span>kneels</span>';ui.endingText.textContent='You bound the fire to your own heart. Power surges through you as the cottages fall dark. The hound stays close—but even it watches you differently now. The people will remember.';}ui.ending.classList.remove('hidden');}
function interaction(){if(!gameOn||mode==='ending')return;const a=Math.hypot(player.x-keeper.x,player.y-keeper.y),b=Math.hypot(player.x-shrine.x,player.y-shrine.y);if(mode==='explore'&&a<100){ui.dialog.classList.remove('hidden');mode='dialog';return;}if(mode==='hunt'&&embers>=5&&b<120){ui.choice.classList.remove('hidden');mode='choice';return;}if(mode==='hunt'&&b<120)toast('The shrine is cold. Gather all five ember-sparks first.');else if(a<100)toast('Mara is waiting. Press E to hear her request.');else if(b<130)toast(embers>=5?'Press E to choose the fate of the flame.':'The old shrine needs five ember-sparks.');else toast('Nothing nearby answers your call.');}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='e')interaction();if(k===' '&&!e.repeat)dodge();if(k==='q'&&!e.repeat)cast();});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointerdown',e=>{if(e.button===0)attack();});
document.querySelectorAll('.touchbtn').forEach(b=>{const k=b.dataset.key,a=b.dataset.action;if(k){b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false));}else b.addEventListener('pointerdown',e=>{e.preventDefault();if(a==='attack')attack();if(a==='spell')cast();if(a==='dodge')dodge();if(a==='talk')interaction();});});
function burst(x,y,color,n){const p=pos(x,y);for(let i=0;i<n;i++){const m=mesh(new THREE.SphereGeometry(.035+rand()*.04,5,4),new THREE.MeshBasicMaterial({color,transparent:true}),scene);m.position.set(p.x,.7+rand()*1.1,p.z);m.userData={vx:(rand()-.5)*3,vy:1+rand()*3,vz:(rand()-.5)*3,t:.5+rand()*.6,max:1};m.castShadow=false;particles.push(m);}}
function attack(){if(!gameOn||['dialog','choice','ending'].includes(mode)||player.attack>0)return;player.attack=.38;const e=enemies.filter(e=>e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<125).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(e){e.hp-=2;e.hit=.3;const a=Math.atan2(e.y-player.y,e.x-player.x);e.x+=Math.cos(a)*38;e.y+=Math.sin(a)*38;burst(e.x,e.y,'#f3c76e',9);if(e.hp<=0)slay(e);}}
function cast(){if(!gameOn||['dialog','choice','ending'].includes(mode)||player.will<32||player.spell>0)return;player.will-=32;player.spell=.8;burst(player.x,player.y,'#8fe5da',32);enemies.forEach(e=>{if(e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<185){e.hp-=2;e.hit=.35;const a=Math.atan2(e.y-player.y,e.x-player.x);e.x+=Math.cos(a)*68;e.y+=Math.sin(a)*68;if(e.hp<=0)slay(e);}});}
function dodge(){if(!gameOn||player.dodge>0)return;let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(!x&&!y){x=Math.cos(player.face);y=Math.sin(player.face);}const l=Math.hypot(x,y)||1;player.vx=x/l*570;player.vy=y/l*570;player.dodge=.29;player.inv=.55;}
function slay(e){e.alive=false;embers++;player.hp=Math.min(100,player.hp+20);player.will=Math.min(100,player.will+22);motes.push({x:e.x,y:e.y-22,t:0});burst(e.x,e.y,'#ffc775',24);ui.objective.textContent=embers<5?`Ember-sparks gathered: ${embers} / 5`:'All five sparks gathered. Take them to the old shrine.';if(embers===5){ui.questSub.textContent='The shrine is awake. Choose your light.';toast('Five sparks! The old shrine glows to the east.');}}
function die(){gameOn=false;mode='ending';ui.endingEyebrow.textContent='The mire claims another';ui.endingTitle.innerHTML='The light <span>fades</span>';ui.endingText.textContent='The ember-wisps overwhelm you. The keeper’s lantern flickers on, still waiting for a champion.';ui.ending.classList.remove('hidden');}

